{
  "name": "图形标注与ROI对象",
  "name_en": "Graphic Annotation and ROI Object",
  "manufacturer": "Nion",
  "description": "用于科学成像软件中的图形标注与感兴趣区域（ROI）对象，可表示矩形、椭圆、直线、点、环形、楔形等覆盖图形。它通常用于显微图像或谱图上的区域选择、测量、掩膜生成、交互编辑和结果标注。",
  "description_en": "A graphic annotation and region-of-interest (ROI) object used in scientific imaging software. It can represent overlays such as rectangles, ellipses, lines, points, rings, and wedges, and is typically used on microscopy images or spectra for region selection, measurement, mask generation, interactive editing, and annotation.",
  "tag_hints": [
    "ROI annotation",
    "scientific imaging",
    "mask generation",
    "interactive graphics",
    "image analysis",
    "microscopy overlays"
  ],
  "actions": [
    {
      "action_name": "auto-CAN_REPOSITION",
      "description": "检查该图形是否可重新定位",
      "description_en": "Check whether the graphic can be repositioned"
    },
    {
      "action_name": "auto-CAN_RESHAPE",
      "description": "检查该图形是否可重塑形状",
      "description_en": "Check whether the graphic can be reshaped"
    },
    {
      "action_name": "auto-CAN_ROTATE",
      "description": "检查该图形是否可旋转",
      "description_en": "Check whether the graphic can be rotated"
    },
    {
      "action_name": "auto-update_uuids",
      "description": "更新图形相关的UUID引用",
      "description_en": "Update UUID references associated with the graphic"
    },
    {
      "action_name": "auto-source_specifier",
      "description": "获取/设置源对象标识符",
      "description_en": "Get/set the source specifier"
    },
    {
      "action_name": "auto-graphic_id",
      "description": "获取/设置图形ID",
      "description_en": "Get/set the graphic ID"
    },
    {
      "action_name": "auto-stroke_color",
      "description": "获取/设置描边颜色",
      "description_en": "Get/set the stroke color"
    },
    {
      "action_name": "auto-stroke_width",
      "description": "获取/设置描边宽度",
      "description_en": "Get/set the stroke width"
    },
    {
      "action_name": "auto-fill_color",
      "description": "获取/设置填充颜色",
      "description_en": "Get/set the fill color"
    },
    {
      "action_name": "auto-label",
      "description": "获取/设置标签文本",
      "description_en": "Get/set the label text"
    },
    {
      "action_name": "auto-is_position_locked",
      "description": "获取/设置位置锁定状态",
      "description_en": "Get/set the position lock state"
    },
    {
      "action_name": "auto-is_shape_locked",
      "description": "获取/设置形状锁定状态",
      "description_en": "Get/set the shape lock state"
    },
    {
      "action_name": "auto-is_rotation_locked",
      "description": "获取/设置旋转锁定状态",
      "description_en": "Get/set the rotation lock state"
    },
    {
      "action_name": "auto-is_bounds_constrained",
      "description": "获取/设置边界约束状态",
      "description_en": "Get/set the bounds-constrained state"
    },
    {
      "action_name": "auto-role",
      "description": "获取/设置图形角色",
      "description_en": "Get/set the graphic role"
    },
    {
      "action_name": "auto-project",
      "description": "获取所属项目",
      "description_en": "Get the associated project"
    },
    {
      "action_name": "auto-display_item",
      "description": "获取关联的显示项",
      "description_en": "Get the associated display item"
    },
    {
      "action_name": "auto-create_proxy",
      "description": "创建该图形的代理引用",
      "description_en": "Create a proxy reference for the graphic"
    },
    {
      "action_name": "auto-item_specifier",
      "description": "获取项目标识信息",
      "description_en": "Get the item specifier"
    },
    {
      "action_name": "auto-clone",
      "description": "复制该图形",
      "description_en": "Clone the graphic"
    },
    {
      "action_name": "auto-mime_data_dict",
      "description": "获取用于剪贴板或拖放的数据字典",
      "description_en": "Get a data dictionary for clipboard or drag-and-drop use"
    },
    {
      "action_name": "auto-write_to_dict",
      "description": "将图形写出为字典",
      "description_en": "Write the graphic to a dictionary"
    },
    {
      "action_name": "auto-read_from_mime_data",
      "description": "从MIME数据读取图形",
      "description_en": "Read the graphic from MIME data"
    },
    {
      "action_name": "auto-read_properties_from_dict",
      "description": "从字典读取图形属性",
      "description_en": "Read graphic properties from a dictionary"
    },
    {
      "action_name": "auto-source",
      "description": "获取/设置关联源对象",
      "description_en": "Get/set the associated source object"
    },
    {
      "action_name": "auto-used_role",
      "description": "获取当前生效的图形角色",
      "description_en": "Get the effective graphic role"
    },
    {
      "action_name": "auto-used_stroke_style",
      "description": "获取当前生效的描边样式",
      "description_en": "Get the effective stroke style"
    },
    {
      "action_name": "auto-used_fill_style",
      "description": "获取当前生效的填充样式",
      "description_en": "Get the effective fill style"
    },
    {
      "action_name": "auto-used_stroke_width",
      "description": "获取当前生效的描边宽度",
      "description_en": "Get the effective stroke width"
    },
    {
      "action_name": "auto-color",
      "description": "获取/设置图形颜色",
      "description_en": "Get/set the graphic color"
    },
    {
      "action_name": "auto-draw",
      "description": "绘制该图形",
      "description_en": "Draw the graphic"
    },
    {
      "action_name": "auto-test",
      "description": "测试给定点是否命中该图形或其可编辑部分",
      "description_en": "Test whether a given point hits the graphic or one of its editable parts"
    },
    {
      "action_name": "auto-get_region",
      "description": "获取对应的区域对象",
      "description_en": "Get the corresponding region object"
    },
    {
      "action_name": "auto-get_mask_item",
      "description": "获取对应的掩膜项",
      "description_en": "Get the corresponding mask item"
    },
    {
      "action_name": "auto-get_mask",
      "description": "生成该图形对应的掩膜",
      "description_en": "Generate a mask corresponding to the graphic"
    },
    {
      "action_name": "auto-has_attribute",
      "description": "检查是否支持某个属性",
      "description_en": "Check whether a given attribute is supported"
    },
    {
      "action_name": "auto-get_attributes",
      "description": "获取支持的属性列表",
      "description_en": "Get the list of supported attributes"
    },
    {
      "action_name": "auto-begin_drag",
      "description": "开始拖动编辑",
      "description_en": "Begin drag editing"
    },
    {
      "action_name": "auto-end_drag",
      "description": "结束拖动编辑",
      "description_en": "End drag editing"
    },
    {
      "action_name": "auto-adjust_part",
      "description": "在交互编辑时调整图形的某一部分",
      "description_en": "Adjust a part of the graphic during interactive editing"
    },
    {
      "action_name": "auto-nudge",
      "description": "按给定增量微移图形",
      "description_en": "Nudge the graphic by a given delta"
    },
    {
      "action_name": "auto-label_position",
      "description": "计算标签位置",
      "description_en": "Calculate the label position"
    },
    {
      "action_name": "auto-reset_position",
      "description": "重置图形位置",
      "description_en": "Reset the graphic position"
    },
    {
      "action_name": "auto-test_label",
      "description": "测试给定点是否命中标签",
      "description_en": "Test whether a given point hits the label"
    },
    {
      "action_name": "auto-draw_label",
      "description": "绘制图形标签",
      "description_en": "Draw the graphic label"
    }
  ]
}

